    68→	);
    69→}
    70→
    71→interface BuilderCanvasProps {
    72→	questions: Question[];
    73→	onQuestionsChange: (questions: Question[]) => void;
    74→	activeDragItem: DragItem | null;
    75→	overId: string | null;
    76→}
    77→
    78→export function BuilderCanvas({
    79→	questions,
    80→	onQuestionsChange,
    81→	activeDragItem,
    82→	overId,
    83→}: BuilderCanvasProps) {
    84→	const { survey, selectedQuestionId, setSelectedQuestionId, activeTab } =
    85→		useSurveyBuilder();
    86→
    87→	const queryClient = useQueryClient();
    88→
    89→	// Make canvas droppable
    90→	const { setNodeRef, isOver } = useDroppable({
    91→		id: "canvas",
    92→	});
    93→
    94→	const createMutation = useMutation(
    95→		orpc.question.create.mutationOptions({
    96→			onSuccess: (newQuestion) => {
    97→				onQuestionsChange([...questions, newQuestion]);
    98→				setSelectedQuestionId(newQuestion.id);
    99→				queryClient.invalidateQueries({ queryKey: ["question"] });
   100→				toast.success("Question added");
   101→			},
   102→			onError: (error) => {
   103→				toast.error(error.message || "Failed to create question");
   104→			},
   105→		}),
   106→	);
   107→
   108→	const handleAddQuestion = () => {
   109→		createMutation.mutate({
   110→			surveyId: survey.id,
   111→			type: "text",
   112→			title: "New Question",
   113→			order: (questions || []).length,
   114→		});
   115→	};
   116→
   117→	const safeQuestions = questions || [];
   118→
   119→	if (activeTab === "preview") {
   120→		return (
   121→			<div className="flex flex-1 items-center justify-center overflow-y-auto bg-neutral-50 p-8">
   122→				<div className="w-full max-w-2xl">
   123→					<AnimatePresence mode="popLayout">
   124→						{safeQuestions.length === 0 ? (
   125→							<motion.div
   126→								key="empty-preview"
   127→								initial={{ opacity: 0, scale: 0.95 }}
   128→								animate={{ opacity: 1, scale: 1 }}
   129→								exit={{ opacity: 0, scale: 0.95 }}
   130→								transition={{ duration: 0.2 }}
   131→							>
   132→								<Card className="border-dashed">
   133→									<CardContent className="flex flex-col items-center justify-center py-16">
   134→										<ClipboardList className="mb-4 h-12 w-12 text-neutral-300" />
   135→										<p className="text-neutral-500">
   136→											Add questions to preview your survey
   137→										</p>
   138→									</CardContent>
   139→								</Card>
   140→							</motion.div>
   141→						) : (
   142→							<div className="space-y-6">
   143→								{safeQuestions.map((question, index) => (
   144→									<motion.div
   145→										key={question.id}
   146→										initial={{ opacity: 0, y: 20 }}
   147→										animate={{ opacity: 1, y: 0 }}
   148→										exit={{ opacity: 0, x: -100 }}
   149→										transition={{ duration: 0.2, delay: index * 0.05 }}
   150→										layout
   151→									>
   152→										<Card>
   153→											<CardContent className="p-6">
   154→												<div className="mb-4">
   155→													<span className="mb-2 block font-bold text-[10px] text-violet-500 uppercase tracking-widest">
   156→														Question {index + 1} of {safeQuestions.length}
   157→													</span>
   158→													<h2 className="font-semibold text-lg">
   159→														{question.title}
   160→													</h2>
   161→													{question.description && (
   162→														<p className="mt-1 text-neutral-500 text-sm">
   163→															{question.description}
   164→														</p>
   165→													)}
   166→												</div>
   167→												<div className="rounded-lg border border-neutral-200 border-dashed bg-neutral-50 p-4 text-center text-neutral-400 text-sm">
   168→													{question.type.replace("_", " ")} question preview
   169→												</div>
   170→											</CardContent>
   171→										</Card>
   172→									</motion.div>
   173→								))}
   174→							</div>
   175→						)}
   176→					</AnimatePresence>
   177→				</div>
   178→			</div>
   179→		);
   180→	}
   181→
   182→	return (
   183→		<div
   184→			ref={setNodeRef}
   185→			className={`flex flex-1 flex-col overflow-y-auto bg-neutral-50/50 p-6 transition-colors ${
   186→				isOver ? "bg-violet-50/50" : ""
   187→			}`}
   188→		>
   189→			<div className="mx-auto w-full max-w-2xl space-y-4">
   190→				<AnimatePresence mode="popLayout">
   191→					{safeQuestions.length === 0 ? (
   192→						<motion.div
   193→							key="empty-state"
   194→							initial={{ opacity: 0, scale: 0.95 }}
   195→							animate={{ opacity: 1, scale: 1 }}
