   224→							<LayoutGroup>
   225→								<SortableContext
   226→									items={safeQuestions.map((q) => q.id)}
   227→									strategy={verticalListSortingStrategy}
   228→								>
   229→									{(() => {
   230→										// Calculate drop position based on overId
   231→										const dropIndex = overId
   232→											? safeQuestions.findIndex((q) => q.id === overId)
   233→											: safeQuestions.length;
   234→
   235→										// Get the question type being dragged
   236→										const draggedQuestionType =
   237→											activeDragItem?.type === "palette"
   238→												? activeDragItem.questionType
   239→												: undefined;
   240→
   241→										// Build items array with drop indicator at correct position
   242→										const items: React.ReactNode[] = [];
