   261→												isOver &&
   262→												activeDragItem?.type === "palette" &&
   263→												index >= dropIndex;
   264→
   265→											// Add the question card
   266→											items.push(
   267→												<motion.div
   268→													key={question.id}
   269→													layout
   270→													initial={{ opacity: 0, y: 20, scale: 0.95 }}
   271→													animate={{
   272→														opacity: 1,
   273→														y: shouldShift ? 80 : 0,
   274→														scale: 1,
   275→													}}
   276→													exit={{
   277→														opacity: 0,
   278→														scale: 0.95,
   279→														transition: { duration: 0.15 },
   280→													}}
   281→													transition={{
   282→														type: "spring",
   283→														stiffness: 400,
   284→														damping: 30,
   285→														mass: 0.8,
   286→													}}
   287→												>
   288→													<QuestionCard
   289→														question={question}
   290→														isSelected={selectedQuestionId === question.id}
   291→														onSelect={() => setSelectedQuestionId(question.id)}
   292→														questions={safeQuestions}
   293→														onQuestionsChange={onQuestionsChange}
   294→													/>
   295→												</motion.div>,
   296→											);
   297→										});
   298→
   299→										// Add indicator at end if hovering at last position or over canvas
   300→										if (
   301→											isOver &&
   302→											activeDragItem?.type === "palette" &&
   303→											dropIndex >= safeQuestions.length
   304→										) {
   305→											items.push(
   306→												<DropIndicator
   307→													key="drop-indicator-end"
   308→													questionType={draggedQuestionType}
   309→												/>,
   310→											);
   311→										}
   312→
   313→										return items;
   314→									})()}
   315→								</SortableContext>
   316→							</LayoutGroup>
   317→
   318→							<motion.div
   319→								initial={{ opacity: 0 }}
   320→								animate={{ opacity: 1 }}
   321→								transition={{ delay: 0.1 }}
   322→							>
   323→								<Button
   324→									variant="outline"
   325→									className="w-full border-dashed"
   326→									onClick={handleAddQuestion}
   327→									disabled={createMutation.isPending}
   328→								>
   329→									<Plus className="mr-2 h-4 w-4" />
   330→									Add Question
   331→								</Button>
   332→							</motion.div>
   333→						</>
   334→					)}
   335→				</AnimatePresence>
   336→			</div>
   337→		</div>
   338→	);
   339→}
